const rows = $input.all().map(item => item.json).filter(row => row.url);
if (!rows.length) return [{ json: { route: 'empty' } }];
const row = rows[0];
const id = String(row.id || '').toLowerCase();
let validUrl = false;
try { validUrl = new URL(row.url).protocol === 'https:'; } catch {}
if (!validUrl || !/^[a-f0-9]{12}$/.test(id)) return [{ json: { route: 'invalid', url: row.url } }];
return [{ json: { ...row, id, route: 'ready' } }];

const html = typeof $json.data === 'string' ? $json.data : '';
let ld = '';
const re = /<script[^>]*type=[\"']application\/ld\+json[\"'][^>]*>([\s\S]*?)<\/script>/gi;
let match;
while ((match = re.exec(html)) !== null) {
  if (/JobPosting/i.test(match[1])) { ld = match[1]; break; }
}
const plain = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ')
  .trim();
let vacancy_text = (ld ? ld + '\n' + plain : plain).slice(0, 12000);
if (vacancy_text.length < 200) vacancy_text = '';
return [{ json: { vacancy_text } }];

const esc = value => String(value ?? '—').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;');
const locale = ['en', 'pl', 'ru', 'uk'].includes($('When Called').first().json.ui_language) ? $('When Called').first().json.ui_language : 'pl';
const copy = {
  en: { title: 'Could not parse vacancy details', unreadable: 'Page could not be read', fetched: 'The vacancy page was fetched, but its details could not be parsed. Review the posting manually.', readFail: 'Could not read the vacancy page. Review it manually using the link.', must: 'Must have', nice: 'Nice to have', unreadableNote: '⚠️ Could not read the page; decide manually.', parseNote: '⚠️ Details could not be parsed; review manually.', open: 'Open vacancy' },
  pl: { title: 'Nie udało się odczytać szczegółów oferty', unreadable: 'Nie udało się otworzyć strony', fetched: 'Strona oferty została pobrana, ale nie udało się odczytać szczegółów. Sprawdź ją ręcznie.', readFail: 'Nie udało się odczytać strony oferty. Sprawdź ją ręcznie pod podanym linkiem.', must: 'Wymagania konieczne', nice: 'Mile widziane', unreadableNote: '⚠️ Nie udało się odczytać strony; zdecyduj ręcznie.', parseNote: '⚠️ Nie udało się odczytać szczegółów; sprawdź ręcznie.', open: 'Otwórz ofertę' },
  ru: { title: 'Не удалось разобрать вакансию', unreadable: 'Не удалось прочитать страницу', fetched: 'Страница вакансии загружена, но детали не удалось разобрать. Проверьте объявление вручную.', readFail: 'Не удалось прочитать страницу вакансии. Проверьте её вручную по ссылке.', must: 'Обязательные требования', nice: 'Будет преимуществом', unreadableNote: '⚠️ Страницу прочитать не удалось; примите решение вручную.', parseNote: '⚠️ Детали не разобраны; проверьте вручную.', open: 'Открыть вакансию' },
  uk: { title: 'Не вдалося розібрати вакансію', unreadable: 'Не вдалося прочитати сторінку', fetched: 'Сторінку вакансії завантажено, але деталі не вдалося розібрати. Перевір оголошення вручну.', readFail: 'Не вдалося прочитати сторінку вакансії. Перевір її вручну за посиланням.', must: 'Обов’язкові вимоги', nice: 'Буде перевагою', unreadableNote: '⚠️ Сторінку не вдалося прочитати; прийми рішення вручну.', parseNote: '⚠️ Деталі не розібрані; перевір вручну.', open: 'Відкрити вакансію' }
};
const list = value => Array.isArray(value) && value.length ? value.slice(0, 6).map(item => '• ' + esc(item)).join('<br>') : '—';
const row = $('Validate queue row').first().json;
const page = $('Pick and clean text').first().json;
const raw = $('Parse vacancy with LLM').isExecuted ? $('Parse vacancy with LLM').first().json.text || '' : '';
let vacancy = { title: page.vacancy_text ? copy[locale].title : copy[locale].unreadable, company: null, location: null, seniority: null, employment_type: null, must_have: [], nice_to_have: [], summary: page.vacancy_text ? copy[locale].fetched : copy[locale].readFail };
let parseFailed = false;
if (raw) { try { vacancy = JSON.parse(raw.replace(/```json|```/g, '').trim()); } catch { parseFailed = true; } }
const url = new URL(row.url);
const note = !page.vacancy_text ? `<br><br>${copy[locale].unreadableNote}` : parseFailed || !raw ? `<br><br>${copy[locale].parseNote}` : '';
const card = `<b>${esc(vacancy.title)}</b><br>${esc(vacancy.company)} · ${esc(vacancy.location)}<br>${esc(vacancy.seniority)} · ${esc(vacancy.employment_type)}<br><br><b>${copy[locale].must}</b><br>${list(vacancy.must_have)}<br><br><b>${copy[locale].nice}</b><br>${list(vacancy.nice_to_have)}<br><br>${esc(vacancy.summary)}${note}<br><br><a href=\"${esc(url.href)}\">${copy[locale].open}</a>`;
return { json: { card, id: row.id } };
